    """Base class for all expression nodes."""

    text: str = ""

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return "%s(%r)" % (type(self).__name__, self.text)


@dataclass
class Literal(Expr):
    value: Any
    text: str = ""


@dataclass
class Column(Expr):
    name: str
    text: str = ""


@dataclass
class Star(Expr):
    text: str = "*"


@dataclass
class Unary(Expr):
    op: str
    operand: Expr
    text: str = ""


@dataclass
class Not(Expr):
    operand: Expr
    text: str = ""


@dataclass
class Binary(Expr):
    op: str
    left: Expr
    right: Expr
    text: str = ""


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool
    text: str = ""


@dataclass
class InList(Expr):
    operand: Expr
    items: List[Expr]
    negated: bool
    text: str = ""


@dataclass
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool
    text: str = ""


@dataclass
class Like(Expr):
    operand: Expr
    pattern: Expr
    negated: bool
    text: str = ""


@dataclass
class Func(Expr):
    #: The function name, upper-cased.
    name: str
    args: List[Expr]
    #: True only for ``COUNT(*)``.
    star: bool = False
    text: str = ""


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    desc: bool = False


@dataclass
class Query:
    distinct: bool
    star: bool
    columns: List[SelectItem]
    table: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def children(expr: Expr) -> List[Expr]:
    """Return the direct children of an expression node."""
    if isinstance(expr, Unary):
        return [expr.operand]
    if isinstance(expr, Not):
        return [expr.operand]
    if isinstance(expr, Binary):
        return [expr.left, expr.right]
    if isinstance(expr, IsNull):
        return [expr.operand]
    if isinstance(expr, InList):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, Func):
        return list(expr.args)
    return []


def walk(expr: Expr) -> Iterator[Expr]:
    """Yield ``expr`` and every descendant expression."""
    yield expr
    for child in children(expr):
        yield from walk(child)


def _literal_key(value: Any) -> Any:
    # Keep booleans distinct from numbers (True == 1 in Python).
    return (type(value).__name__, value)


def signature(expr: Expr) -> Any:
    """A hashable structural key, ignoring source text and name case."""
    if isinstance(expr, Literal):
        return ("literal", _literal_key(expr.value))
    if isinstance(expr, Column):
        return ("column", expr.name.lower())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, Unary):
        return ("unary", expr.op, signature(expr.operand))
    if isinstance(expr, Not):
        return ("not", signature(expr.operand))
    if isinstance(expr, Binary):
        op = "!=" if expr.op == "<>" else expr.op
        return ("binary", op, signature(expr.left), signature(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, signature(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            expr.negated,
            signature(expr.operand),
            tuple(signature(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            signature(expr.operand),
            signature(expr.low),
            signature(expr.high),
        )
    if isinstance(expr, Like):
        return ("like", expr.negated, signature(expr.operand), signature(expr.pattern))
    if isinstance(expr, Func):
        return ("func", expr.name.upper(), expr.star, tuple(signature(a) for a in expr.args))
    raise TypeError("unknown expression node: %r" % (expr,))

